func (c *Client) Charge(ctx context.Context, amount int64, card string) (*Receipt, error) {
	var lastErr error
	for attempt := 0; attempt < 3; attempt++ {
		body := strings.NewReader(fmt.Sprintf(`{"amount":%d,"card":%q}`, amount, card))
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.base+"/v1/charges", body)
		if err != nil {
			return nil, err
		}
		resp, err := c.http.Do(req)
		if err == nil {
			if resp.StatusCode < 500 {
				defer resp.Body.Close()
				return decodeReceipt(resp.Body)
			}
			resp.Body.Close()
			lastErr = fmt.Errorf("charge: status %d", resp.StatusCode)
		} else {
			lastErr = err
		}
		time.Sleep(time.Duration(attempt+1) * 200 * time.Millisecond)
	}
	return nil, lastErr
}
